#include <iostream>
#include <queue>
using namespace std;

#define MAX 50

class Node {
public:
    int vertex;
    Node* next;
    Node(int v) {
        vertex = v;
        next = NULL;
    }
};

class Graph {
    Node* adj[MAX];
    int visited[MAX];
    int n;
public:
    Graph(int num) {
        n = num;
        for(int i = 0; i < n; i++) {
            adj[i] = NULL;
            visited[i] = 0;
        }
    }

    void insertEdge(int u, int v) {
        // For u -> v
        Node* newNode = new Node(v);
        newNode->next = adj[u];
        adj[u] = newNode;

        // For v -> u (undirected graph)
        newNode = new Node(u);
        newNode->next = adj[v];
        adj[v] = newNode;
    }

    void createGraph() {
        int edges;
        cout << "Enter number of edges: ";
        cin >> edges;

        cout << "Enter edges (u v):\n";
        for(int i = 0; i < edges; i++) {
            int u, v;
            cin >> u >> v;
            insertEdge(u, v);
        }
    }

    void displayGraph() {
        for(int i = 0; i < n; i++) {
            cout << "\nVertex " << i << " -> ";
            Node* temp = adj[i];
            while(temp != NULL) {
                cout << temp->vertex << " ";
                temp = temp->next;
            }
        }
        cout << endl;
    }

    void resetVisited() {
        for(int i = 0; i < n; i++)
            visited[i] = 0;
    }

    void DFS(int start) {
        cout << "DFS : ";
        resetVisited();
        DFSrec(start);
        cout << endl;
    }

    void DFSrec(int v) {
        visited[v] = 1;
        cout << v << " ";
        Node* temp = adj[v];
        while(temp != NULL) {
            if(!visited[temp->vertex]) {
                DFSrec(temp->vertex);
            }
            temp = temp->next;
        }
    }

    void BFS(int start) {
        cout << "BFS : ";
        resetVisited();

        queue<int> q;
        visited[start] = 1;
        q.push(start);

        while(!q.empty()) {
            int v = q.front();
            q.pop();
            cout << v << " ";

            Node* temp = adj[v];
            while(temp != NULL) {
                if(!visited[temp->vertex]) {
                    visited[temp->vertex] = 1;
                    q.push(temp->vertex);
                }
                temp = temp->next;
            }
        }
        cout << endl;
    }
};

int main() {
    int n;
    cout << "Enter number of vertices: ";
    cin >> n;

    Graph g(n);

    g.createGraph();
    g.displayGraph();

    int start;
    cout << "\nEnter start vertex: ";
    cin >> start;

    g.DFS(start);
    g.BFS(start);

    return 0;
}
